const ALLOWED_HEADERS = 'authorization, x-client-info, apikey, content-type';
const ALLOWED_METHODS = 'GET, POST, PUT, PATCH, DELETE, OPTIONS';

function parseAllowedOrigins(): Set<string> {
  const raw = Deno.env.get('ALLOWED_ORIGINS') ?? '';
  return new Set(
    raw
      .split(',')
      .map((origin) => origin.trim())
      .filter(Boolean),
  );
}

let cachedOrigins: Set<string> | null = null;

function getAllowedOrigins(): Set<string> {
  if (!cachedOrigins) {
    cachedOrigins = parseAllowedOrigins();
  }
  return cachedOrigins;
}

/** Origin-aware CORS headers. Set ALLOWED_ORIGINS (comma-separated) in env. */
export function getCorsHeaders(req: Request): Record<string, string> {
  const headers: Record<string, string> = {
    'Access-Control-Allow-Headers': ALLOWED_HEADERS,
    'Access-Control-Allow-Methods': ALLOWED_METHODS,
  };

  const origin = req.headers.get('Origin');
  if (origin && getAllowedOrigins().has(origin)) {
    headers['Access-Control-Allow-Origin'] = origin;
    headers['Vary'] = 'Origin';
  }

  return headers;
}

/**
 * Delivery vs yard self-pickup. PIN create / PIN email / lock confirm must skip delivery.
 *
 * Primary flag: addons.isDelivery (and deliveryService). Also honor delivery_type and
 * always-delivered catalog services (dumpster #1, dump trailer with delivery #4) when
 * the JSON flag is missing.
 */

function asRecord(value: unknown): Record<string, unknown> {
  if (value && typeof value === "object" && !Array.isArray(value)) {
    return value as Record<string, unknown>;
  }
  if (typeof value === "string") {
    try {
      const parsed = JSON.parse(value);
      if (parsed && typeof parsed === "object" && !Array.isArray(parsed)) {
        return parsed as Record<string, unknown>;
      }
    } catch {
      // ignore
    }
  }
  return {};
}

/** Catalog services that are always company delivery (not a yard padlock pickup). */
export const ALWAYS_DELIVERY_PLAN_IDS = [1, 4];

export function isDeliveryBooking(
  booking: Record<string, unknown> | null | undefined,
): boolean {
  if (!booking) return false;
  const addons = asRecord(booking.addons);
  const plan = asRecord(booking.plan);
  if (addons.isDelivery === true || addons.deliveryService === true) return true;
  if (booking.delivery_service === true) return true;
  if (String(booking.delivery_type || "").toLowerCase() === "delivery") return true;
  const planId = Number(plan.id);
  return ALWAYS_DELIVERY_PLAN_IDS.includes(planId);
}

/**
 * True when this booking should get a yard padlock PIN (create, confirm, email/SMS).
 * Delivery is always excluded, even if the plan name contains "trailer".
 */
export function bookingNeedsYardLockPin(
  booking: Record<string, unknown> | null | undefined,
): boolean {
  if (!booking || isDeliveryBooking(booking)) return false;
  const plan = asRecord(booking.plan);
  const name = String(plan.name ?? booking.service_name ?? "").toLowerCase();
  const serviceType = String(plan.service_type ?? booking.service_type ?? "");
  return (
    serviceType === "trailer_rental" ||
    Number(plan.id) === 2 ||
    Number(plan.id) === 5 ||
    name.includes("dump loader") ||
    name.includes("dump trailer") ||
    name.includes("trailer") ||
    plan.customer_pickup === true
  );
}

/**
 * Flexible parsers for Igloohome activity payloads.
 *
 * Bridge jobType 15 (GET_LOGS) often completes with only `opResult: { result: 0 }`
 * (operation success) and no log array. Real history is on:
 *   GET /igloohome/devices/{deviceId}/activity
 * after the Bridge pull uploads logs to the cloud.
 */

export const IGLOOHOME_API_BASE_URL = "https://api.igloodeveloper.co/igloohome";

export type LockEventKind = "unlock" | "lock" | "breakin";

export type LockActivityEvent = {
  eventType: LockEventKind;
  eventTimestamp: string;
  pinCode: string | null;
  logType: number | null;
  keyId: string | null;
  operationId: string | null;
  deviceId: string | null;
  raw: Record<string, unknown>;
};

/**
 * Numeric activity log codes from the igloohome webhook (event type 5).
 * These arrive as `logType` on each entry in `activityLogs[]`.
 */
export const LOCK_LOG_TYPES = new Set([
  37, // Bluetooth lock
  49, // lock via keypad/button
  51, // lock with key/thumbturn
]);

export const UNLOCK_LOG_TYPES = new Set([
  11, // Bluetooth unlock
  18,
  19,
  20, // one-time PIN
  21,
  22,
  23,
  24,
  25,
  26, // unlock with the various PIN types
  50, // unlock via button
  52, // unlock with key/thumbturn
  56, // fingerprint unlock
]);

export const BREAKIN_LOG_TYPE = 53;

/** Map a numeric igloohome logType to an event kind, or null if not access-related. */
export function logTypeToEventKind(logType: unknown): LockEventKind | null {
  const n = typeof logType === "number"
    ? logType
    : typeof logType === "string" && /^\d+$/.test(logType.trim())
    ? Number(logType.trim())
    : null;
  if (n === null) return null;
  if (n === BREAKIN_LOG_TYPE) return "breakin";
  if (UNLOCK_LOG_TYPES.has(n)) return "unlock";
  if (LOCK_LOG_TYPES.has(n)) return "lock";
  return null;
}

function extractLogType(entry: Record<string, unknown>): number | null {
  const val = entry.logType ?? entry.log_type;
  if (typeof val === "number" && Number.isFinite(val)) return val;
  if (typeof val === "string" && /^\d+$/.test(val.trim())) return Number(val.trim());
  return null;
}

function asRecord(value: unknown): Record<string, unknown> | null {
  if (value && typeof value === "object" && !Array.isArray(value)) {
    return value as Record<string, unknown>;
  }
  return null;
}

function pickString(obj: Record<string, unknown>, keys: string[]): string | null {
  for (const key of keys) {
    const val = obj[key];
    if (typeof val === "string" && val.trim()) return val.trim();
    if (typeof val === "number") return String(val);
  }
  return null;
}

function isFailedActivity(raw: string | null, entry: Record<string, unknown>): boolean {
  const lower = (raw || "").toLowerCase();
  if (lower.includes("fail") || lower.includes("denied") || lower.includes("invalid")) {
    return true;
  }
  const desc = String(entry.description || "").toLowerCase();
  if (desc.includes("fail") || desc.includes("denied")) return true;
  return false;
}

function normalizeEventType(raw: string | null): LockEventKind | null {
  if (!raw) return null;
  const lower = raw.toLowerCase().replace(/[\s_-]+/g, "");
  // Ignore non-access noise (time sync, battery, etc.)
  if (
    lower.includes("settime") ||
    lower.includes("battery") ||
    lower.includes("bluetooth") ||
    lower.includes("firmware") ||
    lower.includes("heartbeat")
  ) {
    return null;
  }
  if (
    lower.includes("unlock") ||
    lower === "open" ||
    lower === "unlocked" ||
    lower === "pinunlock" ||
    lower === "accessgranted"
  ) {
    return "unlock";
  }
  if (
    lower.includes("relock") ||
    lower.includes("autolock") ||
    lower === "lock" ||
    lower === "close" ||
    lower === "locked" ||
    lower.includes("manualock") ||
    lower.includes("manuallock") ||
    (lower.includes("lock") && !lower.includes("unlock") && !lower.includes("block"))
  ) {
    return "lock";
  }
  return null;
}

/**
 * Webhook activity entries carry `entryDate` as epoch seconds. That is the
 * authoritative time the event happened at the lock — logs can be batched and
 * delivered long after the fact, so never fall back to delivery time.
 */
function extractEpochTimestamp(entry: Record<string, unknown>): string | null {
  for (const key of ["entryDate", "entry_date", "eventDate", "logDate"]) {
    const val = entry[key];
    let num: number | null = null;
    if (typeof val === "number" && Number.isFinite(val)) num = val;
    else if (typeof val === "string" && /^\d{9,13}$/.test(val.trim())) num = Number(val.trim());
    if (num === null || num <= 0) continue;
    // Values below ~1e11 are seconds; above that they are already milliseconds.
    const ms = num < 1e11 ? num * 1000 : num;
    const date = new Date(ms);
    if (!Number.isNaN(date.getTime())) return date.toISOString();
  }
  return null;
}

function extractTimestamp(entry: Record<string, unknown>): string | null {
  const epoch = extractEpochTimestamp(entry);
  if (epoch) return epoch;
  const raw = pickString(entry, [
    "localActionAt",
    "activityTimeAt",
    "timestamp",
    "eventTimestamp",
    "event_timestamp",
    "time",
    "date",
    "createdAt",
    "created_at",
    "lockTime",
    "activityTime",
  ]);
  if (!raw) return null;
  const ms = new Date(raw).getTime();
  if (Number.isNaN(ms)) return null;
  return new Date(ms).toISOString();
}

function extractPin(entry: Record<string, unknown>): string | null {
  const direct = pickString(entry, [
    "pin",
    "pinCode",
    "pin_code",
    "accessCode",
    "access_code",
    "code",
    "pinValue",
  ]);
  if (direct) return direct;
  const extra = asRecord(entry.extra);
  if (extra) {
    return pickString(extra, ["pin", "pinCode", "pin_code", "accessCode", "code"]);
  }
  return null;
}

function extractTypeRaw(entry: Record<string, unknown>): string | null {
  const typeVal = entry.activityType ?? entry.activity_type ?? entry.type ??
    entry.eventType ?? entry.event_type ?? entry.action ?? entry.operation ?? entry.op ??
    entry.logType;
  if (typeof typeVal === "number") {
    return String(typeVal);
  }
  if (typeof typeVal === "string") return typeVal;
  return null;
}

/** Parse a failed PIN attempt for diagnostics (not applied to rental state). */
export function parseFailedPinAttempt(entry: unknown): {
  eventTimestamp: string;
  pinCode: string | null;
  activityType: string;
} | null {
  const obj = asRecord(entry);
  if (!obj) return null;
  const typeRaw = extractTypeRaw(obj);
  if (!isFailedActivity(typeRaw, obj)) return null;
  const lower = (typeRaw || "").toLowerCase();
  if (!lower.includes("unlock") && !lower.includes("pin")) return null;
  const eventTimestamp = extractTimestamp(obj);
  if (!eventTimestamp) return null;
  return {
    eventTimestamp,
    pinCode: extractPin(obj),
    activityType: typeRaw || "PIN_UNLOCK_FAILED",
  };
}

/** Parse a single activity log entry into a normalized event, or null if unusable. */
export function parseActivityLogEntry(entry: unknown): LockActivityEvent | null {
  const obj = asRecord(entry);
  if (!obj) return null;

  // Nested data wrappers
  const nested = asRecord(obj.data) || asRecord(obj.event) || asRecord(obj.activity) || obj;
  const logType = extractLogType(nested) ?? extractLogType(obj);
  const eventTimestamp = extractTimestamp(nested) || extractTimestamp(obj);
  if (!eventTimestamp) return null;

  // Numeric logType is authoritative when present — the webhook sends codes,
  // not descriptive strings, so this must win over the text heuristics below.
  let eventType = logTypeToEventKind(logType);
  if (!eventType) {
    if (logType !== null) return null;
    const typeRaw = extractTypeRaw(nested) || extractTypeRaw(obj);
    if (isFailedActivity(typeRaw, nested) || isFailedActivity(typeRaw, obj)) return null;
    eventType = normalizeEventType(typeRaw);
  }
  if (!eventType) return null;

  return {
    eventType,
    eventTimestamp,
    pinCode: extractPin(nested) || extractPin(obj),
    logType,
    keyId: pickString(nested, ["keyId", "key_id"]) || pickString(obj, ["keyId", "key_id"]),
    operationId: pickString(nested, ["operationId", "operation_id"]) ||
      pickString(obj, ["operationId", "operation_id"]),
    deviceId: pickString(nested, ["deviceId", "device_id", "lockId", "productId"]) ||
      pickString(obj, ["deviceId", "device_id", "lockId", "productId"]),
    raw: obj,
  };
}

/** Strip PIN material so raw payloads can be persisted or logged safely. */
export function redactPins(value: unknown): unknown {
  if (Array.isArray(value)) return value.map(redactPins);
  const obj = asRecord(value);
  if (!obj) return value;
  const out: Record<string, unknown> = {};
  for (const [key, val] of Object.entries(obj)) {
    if (/^(pin|newpin|oldpin|pincode|pin_code|accesscode|access_code|code)$/i.test(key)) {
      out[key] = val ? "[redacted]" : val;
      continue;
    }
    out[key] = redactPins(val);
  }
  return out;
}

/**
 * Walk a job response / webhook body and collect activity log arrays from
 * common nesting locations.
 */
export function extractActivityLogArrays(payload: unknown): unknown[][] {
  const arrays: unknown[][] = [];
  const root = asRecord(payload);
  if (!root) return arrays;

  const candidates = [
    root.activityLogs,
    root.activity_logs,
    root.logs,
    root.events,
    root.history,
    root.payload,
    asRecord(root.jobResponse)?.activityLogs,
    asRecord(root.jobResponse)?.activity_logs,
    asRecord(root.jobResponse)?.logs,
    asRecord(root.jobResponse)?.events,
    asRecord(asRecord(root.jobResponse)?.opResult || {})?.activityLogs,
    asRecord(asRecord(root.jobResponse)?.opResult || {})?.logs,
    asRecord(root.event)?.data,
    asRecord(asRecord(root.event)?.data || {})?.activityLogs,
    asRecord(asRecord(root.event)?.data || {})?.logs,
  ];

  for (const c of candidates) {
    if (Array.isArray(c)) arrays.push(c);
    else if (asRecord(c) && Array.isArray((c as Record<string, unknown>).logs)) {
      arrays.push((c as Record<string, unknown>).logs as unknown[]);
    }
  }

  // Deep scan one level for any array of objects that look like log entries
  if (arrays.length === 0) {
    for (const value of Object.values(root)) {
      if (Array.isArray(value) && value.length > 0 && asRecord(value[0])) {
        arrays.push(value);
      }
      const nested = asRecord(value);
      if (nested) {
        for (const inner of Object.values(nested)) {
          if (Array.isArray(inner) && inner.length > 0 && asRecord(inner[0])) {
            arrays.push(inner);
          }
        }
      }
    }
  }

  return arrays;
}

export function parseActivityLogsFromPayload(payload: unknown): LockActivityEvent[] {
  const events: LockActivityEvent[] = [];
  const seen = new Set<string>();
  for (const arr of extractActivityLogArrays(payload)) {
    for (const entry of arr) {
      const parsed = parseActivityLogEntry(entry);
      if (!parsed) continue;
      const key = `${parsed.eventType}|${parsed.eventTimestamp}|${parsed.pinCode || ""}`;
      if (seen.has(key)) continue;
      seen.add(key);
      events.push(parsed);
    }
  }
  // Also try treating the payload itself as a single event (webhook)
  const single = parseActivityLogEntry(payload) ||
    parseActivityLogEntry(asRecord(payload)?.event) ||
    parseActivityLogEntry(asRecord(asRecord(payload)?.event || {})?.data);
  if (single) {
    const key = `${single.eventType}|${single.eventTimestamp}|${single.pinCode || ""}`;
    if (!seen.has(key)) events.push(single);
  }
  return events.sort(
    (a, b) => new Date(a.eventTimestamp).getTime() - new Date(b.eventTimestamp).getTime(),
  );
}

/** Merge and dedupe events from multiple sources (job payload + REST activity rows). */
export function eventsFromSource(source: unknown): LockActivityEvent[] {
  if (Array.isArray(source)) {
    if (source.length === 0) return [];
    const first = asRecord(source[0]);
    // Already-normalized LockActivityEvent[]
    if (
      first &&
      (first.eventType === "unlock" || first.eventType === "lock" ||
        first.eventType === "breakin") &&
      typeof first.eventTimestamp === "string"
    ) {
      return source as LockActivityEvent[];
    }
    // Raw GET /devices/.../activity payload rows
    const events: LockActivityEvent[] = [];
    const seen = new Set<string>();
    for (const entry of source) {
      const parsed = parseActivityLogEntry(entry);
      if (!parsed) continue;
      const key = `${parsed.eventType}|${parsed.eventTimestamp}|${parsed.pinCode || ""}`;
      if (seen.has(key)) continue;
      seen.add(key);
      events.push(parsed);
    }
    return events;
  }
  return parseActivityLogsFromPayload(source);
}

export function mergeActivityEvents(
  ...sources: Array<LockActivityEvent[] | unknown>
): LockActivityEvent[] {
  const events: LockActivityEvent[] = [];
  const seen = new Set<string>();
  for (const source of sources) {
    for (const parsed of eventsFromSource(source)) {
      const key = `${parsed.eventType}|${parsed.eventTimestamp}|${parsed.pinCode || ""}`;
      if (seen.has(key)) continue;
      seen.add(key);
      events.push(parsed);
    }
  }
  return events.sort(
    (a, b) => new Date(a.eventTimestamp).getTime() - new Date(b.eventTimestamp).getTime(),
  );
}

/**
 * True when Igloohome completed GET_LOGS but returned no log array —
 * commonly `jobResponse.opResult = { result: 0 }` (success with empty body).
 * Prefer reading GET /devices/{id}/activity after the job completes.
 */
export function isEmptyActivityLogPayload(payload: unknown): boolean {
  if (parseActivityLogsFromPayload(payload).length > 0) return false;
  const root = asRecord(payload);
  const jobResponse = asRecord(root?.jobResponse);
  const opResult = asRecord(jobResponse?.opResult);
  if (!opResult) return true;
  const result = opResult.result;
  if (result === 0 || result === "0" || result === null || result === undefined) {
    return true;
  }
  if (Array.isArray(result) && result.length === 0) return true;
  if (asRecord(result)) {
    const nested = asRecord(result);
    for (const key of ["activityLogs", "activity_logs", "logs", "events", "history"]) {
      const arr = nested?.[key];
      if (Array.isArray(arr) && arr.length > 0) return false;
    }
  }
  return extractActivityLogArrays(payload).every((a) => a.length === 0);
}

async function readResponse(res: Response) {
  const text = await res.text();
  try {
    return { text, json: text ? JSON.parse(text) : null };
  } catch {
    return { text, json: null };
  }
}

/**
 * Read stored device activity from Igloohome cloud.
 * Requires an access token issued with ONLY igloohomeapi/get-device-activity.
 */
export async function fetchDeviceActivityRows(
  accessToken: string,
  deviceId: string,
  opts: { maxPages?: number; pageSize?: number } = {},
): Promise<{ rows: unknown[]; error?: string; status?: number }> {
  const maxPages = opts.maxPages ?? 5;
  const pageSize = opts.pageSize ?? 50;
  const rows: unknown[] = [];
  let cursor: string | null = null;

  for (let page = 0; page < maxPages; page++) {
    const qs = new URLSearchParams({ pageSize: String(pageSize) });
    if (cursor) qs.set("cursor", cursor);
    const url = `${IGLOOHOME_API_BASE_URL}/devices/${deviceId}/activity?${qs}`;
    let res: Response;
    try {
      res = await fetch(url, {
        method: "GET",
        headers: {
          Authorization: `Bearer ${accessToken}`,
          Accept: "application/json",
        },
      });
    } catch (err) {
      return { rows, error: `network error fetching device activity: ${err}` };
    }
    const body = await readResponse(res);
    if (!res.ok) {
      return {
        rows,
        error: `GET /devices/.../activity HTTP ${res.status}: ${
          String(body.json?.message || body.json?.error || body.text || "").slice(0, 300)
        }`,
        status: res.status,
      };
    }
    const chunk = Array.isArray(body.json?.payload)
      ? body.json.payload
      : Array.isArray(body.json)
      ? body.json
      : [];
    rows.push(...chunk);
    cursor = typeof body.json?.nextCursor === "string" && body.json.nextCursor
      ? body.json.nextCursor
      : null;
    if (!cursor || chunk.length === 0) break;
  }

  return { rows };
}

/**
 * Verification for the `x-igloocompany-sha256` header on igloohome webhooks.
 *
 * Igloohome documents the signed string as:
 *   METHOD|HOST|URL_PATH|CONTENT_TYPE|DATE|BODY
 *
 * Then HMAC-SHA256 that string using the PKCS#1 RSA public key bytes (DER) as
 * the HMAC key, and RSA-SHA256 verify the digest against the header signature.
 *
 * Env: IGLOOHOME_PUBLIC_KEY — base64 PKCS#1 DER (2048-bit RSA), from
 * dev+support@igloocompany.co
 *
 * Local only: IGLOOHOME_WEBHOOK_ALLOW_UNSIGNED=true accepts posts with no
 * signature header (simulate tools cannot forge Igloohome's RSA signature).
 */

export type WebhookVerifyResult = {
  valid: boolean;
  method: "rsa_public_key" | "unsigned_allowed" | "none";
  reason?: string;
};

function base64ToBytes(b64: string): Uint8Array {
  const clean = b64
    .replace(/-----BEGIN [^-]+-----/g, "")
    .replace(/-----END [^-]+-----/g, "")
    .replace(/\s+/g, "");
  const binary = atob(clean);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
  return bytes;
}

/** Match Node crypto HMAC `.update(payload, 'ascii')`. */
function stringToAsciiBytes(s: string): Uint8Array {
  const bytes = new Uint8Array(s.length);
  for (let i = 0; i < s.length; i++) bytes[i] = s.charCodeAt(i) & 0xff;
  return bytes;
}

function derLength(len: number): number[] {
  if (len < 0x80) return [len];
  const out: number[] = [];
  let n = len;
  while (n > 0) {
    out.unshift(n & 0xff);
    n >>= 8;
  }
  return [0x80 | out.length, ...out];
}

function derWrap(tag: number, contents: Uint8Array): Uint8Array {
  const header = [tag, ...derLength(contents.length)];
  const out = new Uint8Array(header.length + contents.length);
  out.set(header, 0);
  out.set(contents, header.length);
  return out;
}

/** Web Crypto imports SPKI; Igloohome issues PKCS#1 `RSAPublicKey` DER. */
function pkcs1ToSpki(pkcs1: Uint8Array): Uint8Array {
  const algorithmIdentifier = new Uint8Array([
    0x30, 0x0d,
    0x06, 0x09, 0x2a, 0x86, 0x48, 0x86, 0xf7, 0x0d, 0x01, 0x01, 0x01,
    0x05, 0x00,
  ]);
  const bitString = derWrap(0x03, new Uint8Array([0x00, ...pkcs1]));
  const body = new Uint8Array(algorithmIdentifier.length + bitString.length);
  body.set(algorithmIdentifier, 0);
  body.set(bitString, algorithmIdentifier.length);
  return derWrap(0x30, body);
}

async function importPkcs1PublicKey(pkcs1Der: Uint8Array): Promise<CryptoKey> {
  return await crypto.subtle.importKey(
    "spki",
    pkcs1ToSpki(pkcs1Der),
    { name: "RSASSA-PKCS1-v1_5", hash: "SHA-256" },
    false,
    ["verify"],
  );
}

/** HMAC-SHA256(key=publicKeyDer, message=signedString) per Igloohome docs. */
async function hmacSha256(keyBytes: Uint8Array, signed: string): Promise<Uint8Array> {
  const key = await crypto.subtle.importKey(
    "raw",
    keyBytes,
    { name: "HMAC", hash: "SHA-256" },
    false,
    ["sign"],
  );
  const sig = await crypto.subtle.sign("HMAC", key, stringToAsciiBytes(signed));
  return new Uint8Array(sig);
}

/**
 * Build candidate signed strings per Igloohome docs.
 *
 * Supabase Edge may rewrite before the function runs:
 * - `/functions/v1/igloohome-webhook` → `/igloohome-webhook`
 * - `Host: <project>.supabase.co` → `Host: edge-runtime.supabase.com`
 *
 * Igloohome signs the public URL the portal was configured with.
 */
function buildSignedStrings(req: Request, rawBody: string): string[] {
  const url = new URL(req.url);
  const method = req.method.toUpperCase();
  const date = req.headers.get("date") || "";
  const contentType = req.headers.get("content-type") || "application/json";
  const baseContentType = contentType.split(";")[0].trim();

  const hosts = new Set<string>();
  const headerHost = req.headers.get("host");
  if (headerHost) hosts.add(headerHost);
  if (url.host) hosts.add(url.host);
  const hostOverride = Deno.env.get("IGLOOHOME_WEBHOOK_HOST");
  if (hostOverride) hosts.add(hostOverride);
  try {
    const supabaseHost = new URL(Deno.env.get("SUPABASE_URL") || "").host;
    if (supabaseHost) hosts.add(supabaseHost);
  } catch {
    // ignore invalid SUPABASE_URL
  }

  const paths = new Set<string>();
  paths.add(url.pathname);
  if (!url.pathname.startsWith("/functions/v1")) {
    paths.add(`/functions/v1${url.pathname}`);
  } else {
    paths.add(url.pathname.replace(/^\/functions\/v1/, "") || url.pathname);
  }
  const pathOverride = Deno.env.get("IGLOOHOME_WEBHOOK_PATH");
  if (pathOverride) paths.add(pathOverride);

  const contentTypes = contentType === baseContentType
    ? [contentType]
    : [contentType, baseContentType];

  const candidates: string[] = [];
  for (const host of hosts) {
    for (const path of paths) {
      for (const ct of contentTypes) {
        candidates.push(`${method}|${host}|${path}|${ct}|${date}|${rawBody}`);
      }
    }
  }
  return [...new Set(candidates)];
}

export async function verifyIglooWebhook(
  req: Request,
  rawBody: string,
): Promise<WebhookVerifyResult> {
  const publicKeyB64 = Deno.env.get("IGLOOHOME_PUBLIC_KEY")?.trim();
  const allowUnsigned = Deno.env.get("IGLOOHOME_WEBHOOK_ALLOW_UNSIGNED") === "true";

  if (allowUnsigned && !req.headers.get("x-igloocompany-sha256")) {
    return { valid: true, method: "unsigned_allowed" };
  }

  if (!publicKeyB64) {
    return {
      valid: false,
      method: "none",
      reason: "IGLOOHOME_PUBLIC_KEY is not set. Request the webhook public key from dev+support@igloocompany.co.",
    };
  }

  const provided = (req.headers.get("x-igloocompany-sha256") || "")
    .replace(/^"|"$/g, "")
    .trim();
  if (!provided) {
    return { valid: false, method: "rsa_public_key", reason: "Missing x-igloocompany-sha256 header" };
  }

  try {
    const keyBytes = base64ToBytes(publicKeyB64);
    const cryptoKey = await importPkcs1PublicKey(keyBytes);
    const signature = base64ToBytes(provided);
    const candidates = buildSignedStrings(req, rawBody);

    for (const signed of candidates) {
      const hmacDigest = await hmacSha256(keyBytes, signed);
      const ok = await crypto.subtle.verify(
        "RSASSA-PKCS1-v1_5",
        cryptoKey,
        signature,
        hmacDigest,
      );
      if (ok) return { valid: true, method: "rsa_public_key" };
    }

    const url = new URL(req.url);
    console.warn("[igloohome-webhook] Signature verification failed", JSON.stringify({
      publicKey: publicKeyB64,
      publicKeyDerBytes: keyBytes.length,
      host: req.headers.get("host"),
      path: url.pathname,
      date: req.headers.get("date"),
      contentType: req.headers.get("content-type"),
      bodyLen: rawBody.length,
      bodyPreview: rawBody.slice(0, 120),
      candidateCount: candidates.length,
      primaryCandidate: candidates[0] ?? null,
      altCandidate: candidates[1] ?? null,
    }));

    return {
      valid: false,
      method: "rsa_public_key",
      reason: "RSA signature did not match any candidate signed string",
    };
  } catch (err) {
    console.warn("[igloohome-webhook] Signature verification error", JSON.stringify({
      publicKey: publicKeyB64,
      error: err instanceof Error ? err.message : String(err),
    }));
    return {
      valid: false,
      method: "rsa_public_key",
      reason: `Public key verification error: ${err instanceof Error ? err.message : err}`,
    };
  }
}

/**
 * Admin alerts for physical-security and connectivity events on rental locks.
 * Uses the same BREVO_FROM_EMAIL admin address as ensure-lock-pin-ready.
 */

import { sendEmail } from "./notify.ts";

function adminEmail(): string | null {
  return Deno.env.get("LOCK_ALERT_EMAIL") || Deno.env.get("BREVO_FROM_EMAIL") || null;
}

function wrap(title: string, color: string, rows: Array<[string, string]>, note: string): string {
  const cells = rows
    .map(
      ([label, value]) =>
        `<tr><td style="padding:6px 12px 6px 0;color:#64748b;">${label}</td><td style="padding:6px 0;font-weight:600;">${value}</td></tr>`,
    )
    .join("");
  return `
    <div style="font-family:system-ui,-apple-system,sans-serif;max-width:520px;">
      <h2 style="color:${color};margin:0 0 12px;">${title}</h2>
      <table style="border-collapse:collapse;font-size:14px;">${cells}</table>
      <p style="margin:16px 0 0;color:#475569;font-size:14px;">${note}</p>
    </div>
  `;
}

export async function alertBreakInAttempt(details: {
  deviceId: string;
  label?: string | null;
  occurredAt: string;
  orderId?: number | null;
}): Promise<void> {
  const to = adminEmail();
  if (!to) {
    console.error("[lockAlerts] No admin email configured; skipping break-in alert");
    return;
  }
  const html = wrap("Break-in attempt detected", "#b91c1c", [
    ["Lock", details.label || details.deviceId],
    ["Device ID", details.deviceId],
    ["Detected at", new Date(details.occurredAt).toLocaleString("en-US")],
    ["Booking", details.orderId ? `#${details.orderId}` : "Not matched to a booking"],
  ], "The lock reported a tamper / forced-entry attempt (log type 53). Check the equipment.");
  await sendEmail(to, `Break-in attempt on ${details.label || details.deviceId}`, html);
}

export async function alertBridgeOfflineWhileUnlocked(details: {
  bridgeId: string;
  deviceId: string;
  label?: string | null;
  lastStateChangedAt?: string | null;
}): Promise<void> {
  const to = adminEmail();
  if (!to) {
    console.error("[lockAlerts] No admin email configured; skipping bridge-offline alert");
    return;
  }
  const html = wrap("Lock left open and bridge went offline", "#c2410c", [
    ["Lock", details.label || details.deviceId],
    ["Bridge ID", details.bridgeId],
    [
      "Unlocked since",
      details.lastStateChangedAt
        ? new Date(details.lastStateChangedAt).toLocaleString("en-US")
        : "Unknown",
    ],
  ], "Connectivity was lost while the lock was still unlocked, so further activity will not be reported until the bridge reconnects.");
  await sendEmail(to, `Bridge offline with ${details.label || details.deviceId} unlocked`, html);
}

/**
 * Device-level lock tracking, independent of any booking.
 *
 * `rental_tracking_logs` answers "what happened on booking #123". These tables
 * answer "where is this piece of equipment right now", which still needs to be
 * correct when a PIN cannot be matched to a booking (key/thumbturn use, an
 * expired code, a break-in attempt).
 *
 * Shared by igloohome-webhook and the sync-lock-activity poller so both paths
 * converge on the same state, deduplicated by a unique index.
 */

import { type LockActivityEvent, redactPins } from "./iglooActivity.ts";
import { resolveOrderIdByPin } from "./lockEventState.ts";

// deno-lint-ignore no-explicit-any
type SupabaseClient = any;

export type RecordedEvent = {
  event: LockActivityEvent;
  deviceId: string;
  orderId: number | null;
};

export type RecordResult = {
  recorded: RecordedEvent[];
  stored: number;
  skippedDuplicates: number;
};

export function defaultDeviceId(): string | null {
  return Deno.env.get("IGLOOHOME_LOCK_ID") || Deno.env.get("IGLOOHOME_DEVICE_ID") || null;
}

export function defaultBridgeId(): string | null {
  return Deno.env.get("IGLOOHOME_BRIDGE_ID") || null;
}

export async function ensureBridge(
  supabase: SupabaseClient,
  bridgeId: string | null,
): Promise<void> {
  if (!bridgeId) return;
  const { error } = await supabase.from("lock_bridges").upsert(
    { bridge_id: bridgeId, last_event_at: new Date().toISOString() },
    { onConflict: "bridge_id" },
  );
  if (error) console.error("[lockDeviceState] ensureBridge failed:", error.message);
}

/**
 * Register hardware the first time we hear from it, so adding a second lock is
 * plug-and-play — map it to a piece of equipment afterwards in the admin UI.
 */
export async function ensureDevice(
  supabase: SupabaseClient,
  deviceId: string,
  bridgeId: string | null,
): Promise<Record<string, unknown> | null> {
  await ensureBridge(supabase, bridgeId);

  const columns = "device_id, label, bridge_id, current_state, state_changed_at, equipment_id";
  const { data: existing } = await supabase
    .from("lock_devices")
    .select(columns)
    .eq("device_id", deviceId)
    .maybeSingle();

  if (existing) {
    if (bridgeId && existing.bridge_id !== bridgeId) {
      await supabase.from("lock_devices").update({ bridge_id: bridgeId }).eq(
        "device_id",
        deviceId,
      );
    }
    return existing;
  }

  const { data: inserted, error } = await supabase
    .from("lock_devices")
    .insert({ device_id: deviceId, bridge_id: bridgeId, current_state: "unknown" })
    .select(columns)
    .maybeSingle();
  if (error) console.error("[lockDeviceState] ensureDevice insert failed:", error.message);
  return inserted ?? null;
}

/**
 * Persist activity events against their device and roll the device's current
 * state forward. Returns only the events that were new, so callers do not
 * re-notify on a redelivery.
 */
export async function recordDeviceEvents(
  supabase: SupabaseClient,
  events: LockActivityEvent[],
  opts: { deviceId?: string | null; bridgeId?: string | null } = {},
): Promise<RecordResult> {
  const fallbackDeviceId = opts.deviceId || defaultDeviceId();
  const bridgeId = opts.bridgeId || defaultBridgeId();

  const ordered = [...events].sort(
    (a, b) => new Date(a.eventTimestamp).getTime() - new Date(b.eventTimestamp).getTime(),
  );

  const recorded: RecordedEvent[] = [];
  const latestPerDevice = new Map<string, LockActivityEvent>();
  const deviceCache = new Map<string, Record<string, unknown> | null>();
  let stored = 0;
  let skippedDuplicates = 0;

  for (const event of ordered) {
    const deviceId = event.deviceId || fallbackDeviceId;
    if (!deviceId) {
      console.warn("[lockDeviceState] Event with no resolvable device id; skipping");
      continue;
    }
    if (!deviceCache.has(deviceId)) {
      deviceCache.set(deviceId, await ensureDevice(supabase, deviceId, bridgeId));
    }
    const device = deviceCache.get(deviceId) ?? null;

    // The PIN is used in memory to match a booking, then stripped before the
    // payload is stored. It is never written to the table or to the logs.
    const orderId = await resolveOrderIdByPin(supabase, event.pinCode, event.eventTimestamp);

    const { error } = await supabase.from("lock_device_events").insert({
      device_id: deviceId,
      bridge_id: bridgeId,
      event_kind: event.eventType,
      log_type: event.logType,
      occurred_at: event.eventTimestamp,
      order_id: orderId,
      pin_matched: Boolean(event.pinCode && orderId),
      key_id: event.keyId,
      operation_id: event.operationId,
      raw: redactPins(event.raw),
    });

    if (error) {
      // 23505 means an earlier delivery or poll already ingested this entry.
      if (error.code === "23505") skippedDuplicates += 1;
      else console.error("[lockDeviceState] event insert failed:", error.message);
      continue;
    }

    stored += 1;
    recorded.push({ event: { ...event, raw: {} }, deviceId, orderId });

    if (event.eventType === "breakin") {
      await supabase
        .from("lock_devices")
        .update({ last_breakin_at: event.eventTimestamp })
        .eq("device_id", deviceId);
      continue;
    }

    // Entries can arrive batched and out of order; never let a stale entry
    // overwrite a more recent known state.
    const known = latestPerDevice.get(deviceId);
    const previousMs = known
      ? new Date(known.eventTimestamp).getTime()
      : device?.state_changed_at
      ? new Date(String(device.state_changed_at)).getTime()
      : -Infinity;
    if (new Date(event.eventTimestamp).getTime() >= previousMs) {
      latestPerDevice.set(deviceId, event);
    }
  }

  for (const [deviceId, latest] of latestPerDevice) {
    const { error } = await supabase
      .from("lock_devices")
      .update({
        current_state: latest.eventType === "lock" ? "locked" : "unlocked",
        state_changed_at: latest.eventTimestamp,
        last_event_at: latest.eventTimestamp,
      })
      .eq("device_id", deviceId);
    if (error) console.error("[lockDeviceState] state update failed:", error.message);
  }

  return { recorded, stored, skippedDuplicates };
}

/**
 * Lock-event state machine for self-pickup rentals.
 * - First unlock at/after booking start → Mark Rented (status Delivered + rented_out_at)
 * - Lock at/after scheduled end → Mark Returned (status pending_checklist + returned_at)
 * - Grace-hour sweep closes rentals whose last lock fell in/after the end window
 */

import { BOOKING_WINDOW_COLUMNS, getBookingWindow } from "./pinTiming.ts";
import { isDeliveryBooking } from "./deliveryBooking.ts";

// deno-lint-ignore no-explicit-any
type SupabaseClient = any;

export type LockEventInput = {
  orderId: number;
  eventType: "unlock" | "lock" | "breakin";
  eventTimestamp: string;
  notes?: string;
};

function isCustomerPickupBooking(booking: Record<string, unknown>): boolean {
  if (isDeliveryBooking(booking)) return false;
  const plan = (booking.plan || {}) as Record<string, unknown>;
  if (plan.customer_pickup === true) return true;
  const id = Number(plan.id);
  return id === 2 || id === 5;
}

async function invokeNotify(
  supabase: SupabaseClient,
  functionName: string,
  body: Record<string, unknown>,
): Promise<void> {
  const base = Deno.env.get("SUPABASE_URL");
  const key = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY");
  if (!base || !key) {
    console.error(`[lockEventState] Missing SUPABASE_URL/SERVICE_ROLE_KEY for ${functionName}`);
    return;
  }
  try {
    const res = await fetch(`${base}/functions/v1/${functionName}`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${key}`,
      },
      body: JSON.stringify(body),
    });
    if (!res.ok) {
      console.error(`[lockEventState] ${functionName} failed:`, await res.text());
    }
  } catch (err) {
    console.error(`[lockEventState] ${functionName} exception:`, err);
  }
}

/** Insert a tracking log, ignoring unique-constraint duplicates. Returns true if inserted. */
export async function insertTrackingLog(
  supabase: SupabaseClient,
  event: LockEventInput,
): Promise<boolean> {
  const { error } = await supabase.from("rental_tracking_logs").insert({
    order_id: event.orderId,
    event_type: event.eventType,
    event_timestamp: event.eventTimestamp,
    api_sync_timestamp: new Date().toISOString(),
    notes: event.notes || `${event.eventType} event via lock sync`,
  });
  if (error) {
    // Unique violation = already ingested
    if (error.code === "23505" || String(error.message || "").includes("duplicate")) {
      return false;
    }
    console.error(`[lockEventState] insertTrackingLog error:`, error);
    return false;
  }
  return true;
}

async function markRented(
  supabase: SupabaseClient,
  booking: Record<string, unknown>,
  eventTimestamp: string,
): Promise<boolean> {
  if (booking.rented_out_at) return false;
  const { error } = await supabase
    .from("bookings")
    .update({
      rented_out_at: eventTimestamp,
      status: "Delivered",
    })
    .eq("id", booking.id)
    .is("rented_out_at", null);
  if (error) {
    console.error(`[lockEventState] markRented failed for #${booking.id}:`, error);
    return false;
  }
  console.log(`[lockEventState] Booking #${booking.id} marked Rented at ${eventTimestamp}`);

  if (!booking.rental_started_notified_at) {
    await invokeNotify(supabase, "send-rental-started", {
      order_id: booking.id,
      unlock_timestamp: eventTimestamp,
    });
  }
  return true;
}

async function markReturned(
  supabase: SupabaseClient,
  booking: Record<string, unknown>,
  eventTimestamp: string,
): Promise<boolean> {
  if (!booking.rented_out_at || booking.returned_at) return false;
  const { error } = await supabase
    .from("bookings")
    .update({
      returned_at: eventTimestamp,
      status: "pending_checklist",
    })
    .eq("id", booking.id)
    .is("returned_at", null)
    .not("rented_out_at", "is", null);
  if (error) {
    console.error(`[lockEventState] markReturned failed for #${booking.id}:`, error);
    return false;
  }
  console.log(`[lockEventState] Booking #${booking.id} marked Returned at ${eventTimestamp}`);

  if (!booking.return_notified_at) {
    await invokeNotify(supabase, "send-return-confirmation", {
      order_id: booking.id,
      lock_event_timestamp: eventTimestamp,
    });
  }
  return true;
}

/**
 * Apply a single lock/unlock event to the matching booking.
 * Returns a short action description for logging.
 */
export async function applyLockEvent(
  supabase: SupabaseClient,
  event: LockEventInput,
): Promise<string> {
  const inserted = await insertTrackingLog(supabase, event);

  // Break-ins belong on the booking timeline but never move rental state.
  if (event.eventType === "breakin") {
    return inserted ? "logged_breakin" : "duplicate_breakin";
  }

  const { data: booking, error } = await supabase
    .from("bookings")
    .select(
      `id, status, plan, addons, ${BOOKING_WINDOW_COLUMNS}, rented_out_at, returned_at, rental_started_notified_at, return_notified_at`,
    )
    .eq("id", event.orderId)
    .single();

  if (error || !booking) {
    return inserted ? "logged_no_booking" : "skipped";
  }

  if (!isCustomerPickupBooking(booking)) {
    return inserted ? "logged_not_self_pickup" : "skipped";
  }

  const window = getBookingWindow(booking);
  const eventMs = new Date(event.eventTimestamp).getTime();
  if (Number.isNaN(eventMs)) return "invalid_timestamp";

  if (event.eventType === "unlock") {
    if (eventMs >= window.startMs && !booking.rented_out_at) {
      await markRented(supabase, booking, event.eventTimestamp);
      return "marked_rented";
    }
    return inserted ? "logged_unlock" : "duplicate_unlock";
  }

  // lock event
  if (
    eventMs >= window.endMs &&
    booking.rented_out_at &&
    !booking.returned_at
  ) {
    await markReturned(supabase, booking, event.eventTimestamp);
    return "marked_returned";
  }
  return inserted ? "logged_lock" : "duplicate_lock";
}

/**
 * After ingesting events, close any self-pickup rental whose grace hour has
 * passed and that has a lock event at/after the scheduled end but no returned_at.
 */
export async function sweepGraceHourReturns(
  supabase: SupabaseClient,
  now: Date = new Date(),
): Promise<number> {
  const { data: candidates, error } = await supabase
    .from("bookings")
    .select(
      `id, status, plan, addons, ${BOOKING_WINDOW_COLUMNS}, rented_out_at, returned_at, rental_started_notified_at, return_notified_at`,
    )
    .not("rented_out_at", "is", null)
    .is("returned_at", null)
    .not("status", "in", '("Cancelled","Completed","flagged")');

  if (error || !candidates?.length) {
    if (error) console.error("[lockEventState] sweepGraceHourReturns query error:", error);
    return 0;
  }

  let closed = 0;
  const nowMs = now.getTime();

  for (const booking of candidates) {
    if (!isCustomerPickupBooking(booking)) continue;
    const window = getBookingWindow(booking);
    if (nowMs < window.graceEndMs) continue;

    const { data: lockEvent } = await supabase
      .from("rental_tracking_logs")
      .select("event_timestamp")
      .eq("order_id", booking.id)
      .eq("event_type", "lock")
      .gte("event_timestamp", new Date(window.endMs).toISOString())
      .order("event_timestamp", { ascending: false })
      .limit(1)
      .maybeSingle();

    if (!lockEvent?.event_timestamp) continue;

    const ok = await markReturned(supabase, booking, lockEvent.event_timestamp);
    if (ok) closed += 1;
  }

  return closed;
}

/**
 * Resolve order_id from a PIN by looking up active rental_access_codes whose
 * validity window covers the event timestamp.
 */
export async function resolveOrderIdByPin(
  supabase: SupabaseClient,
  pinCode: string | null,
  eventTimestamp: string,
): Promise<number | null> {
  if (!pinCode) return null;
  const { data, error } = await supabase
    .from("rental_access_codes")
    .select("order_id, start_time, end_time, status")
    .eq("access_pin", pinCode)
    .in("status", ["active", "expired", "used"])
    .order("created_at", { ascending: false })
    .limit(10);

  if (error || !data?.length) return null;

  const eventMs = new Date(eventTimestamp).getTime();
  for (const row of data) {
    const start = new Date(row.start_time).getTime();
    const end = new Date(row.end_time).getTime();
    // Allow a small buffer before start (early unlock attempts) and after end
    if (eventMs >= start - 60 * 60 * 1000 && eventMs <= end + 2 * 60 * 60 * 1000) {
      return Number(row.order_id);
    }
  }
  // Fallback: most recent matching PIN
  return Number(data[0].order_id);
}

/**
 * Shared Brevo / Resend email + Brevo / Twilio SMS helpers.
 * SMS_PROVIDER env: "brevo" (default) | "twilio"
 */

const BREVO_API_KEY = Deno.env.get("BREVO_API_KEY");
const BREVO_FROM_EMAIL = Deno.env.get("BREVO_FROM_EMAIL") || "noreply@u-filldumpsters.com";
const BREVO_SMS_SENDER = Deno.env.get("BREVO_SMS_SENDER") || "UFillDump";
const RESEND_API_KEY = Deno.env.get("RESEND_API_KEY");
const SMS_PROVIDER = (Deno.env.get("SMS_PROVIDER") || "brevo").toLowerCase();
const TWILIO_ACCOUNT_SID = Deno.env.get("TWILIO_ACCOUNT_SID");
const TWILIO_AUTH_TOKEN = Deno.env.get("TWILIO_AUTH_TOKEN");
const TWILIO_FROM_NUMBER = Deno.env.get("TWILIO_FROM_NUMBER");

export type SendEmailResult = {
  success: boolean;
  provider?: string;
  error?: string;
  result?: unknown;
  /** Provider message id when available (Brevo messageId / Resend id). */
  messageId?: string;
};

export type SendSmsResult = {
  success: boolean;
  provider?: string;
  skipped?: boolean;
  reason?: string;
  error?: string;
  result?: unknown;
};

/** Normalize to E.164-ish digits; assume US (+1) when 10 digits. */
export function normalizePhoneE164(phone: string | null | undefined): string | null {
  if (!phone) return null;
  const digits = phone.replace(/\D/g, "");
  if (digits.length === 10) return `+1${digits}`;
  if (digits.length === 11 && digits.startsWith("1")) return `+${digits}`;
  if (phone.trim().startsWith("+") && digits.length >= 10) return `+${digits}`;
  return null;
}

export async function sendEmail(
  toEmail: string,
  subject: string,
  htmlContent: string,
  maxRetries = 4,
): Promise<SendEmailResult> {
  let lastError: string | null = null;
  for (let attempt = 1; attempt <= maxRetries; attempt++) {
    const ts = new Date().toISOString();
    try {
      if (BREVO_API_KEY) {
        const brevoResponse = await fetch("https://api.brevo.com/v3/smtp/email", {
          method: "POST",
          headers: {
            "api-key": BREVO_API_KEY,
            "Content-Type": "application/json",
          },
          body: JSON.stringify({
            sender: { email: BREVO_FROM_EMAIL, name: "U-Fill Dumpsters" },
            to: [{ email: toEmail }],
            subject,
            htmlContent,
          }),
        });
        if (brevoResponse.ok) {
          const result = await brevoResponse.json();
          const messageId =
            typeof result?.messageId === "string"
              ? result.messageId
              : typeof result?.messageIds?.[0] === "string"
              ? result.messageIds[0]
              : undefined;
          console.log(
            `[${ts}] [notify] Brevo accepted email to=${toEmail} from=${BREVO_FROM_EMAIL} messageId=${messageId || "unknown"}`,
          );
          return { success: true, provider: "brevo", result, messageId };
        }
        lastError = `Brevo API error: ${await brevoResponse.text()}`;
        console.error(`[${ts}] [notify] Brevo email failed:`, lastError);
      }

      if (RESEND_API_KEY) {
        const resendResponse = await fetch("https://api.resend.com/emails", {
          method: "POST",
          headers: {
            Authorization: `Bearer ${RESEND_API_KEY}`,
            "Content-Type": "application/json",
          },
          body: JSON.stringify({
            from: "U-Fill Dumpsters <noreply@u-filldumpsters.com>",
            to: [toEmail],
            subject,
            html: htmlContent,
          }),
        });
        if (resendResponse.ok) {
          const result = await resendResponse.json();
          const messageId = typeof result?.id === "string" ? result.id : undefined;
          console.log(
            `[${ts}] [notify] Resend accepted email to=${toEmail} messageId=${messageId || "unknown"}`,
          );
          return { success: true, provider: "resend", result, messageId };
        }
        lastError = `Resend API error: ${await resendResponse.text()}`;
        console.error(`[${ts}] [notify] Resend email failed:`, lastError);
      }

      if (!BREVO_API_KEY && !RESEND_API_KEY) {
        return { success: false, error: "No email service configured" };
      }

      if (attempt < maxRetries) {
        await new Promise((r) => setTimeout(r, Math.pow(2, attempt) * 1000));
      }
    } catch (err) {
      lastError = err instanceof Error ? err.message : String(err);
      console.error(`[${ts}] [notify] Email exception:`, lastError);
      if (attempt < maxRetries) {
        await new Promise((r) => setTimeout(r, Math.pow(2, attempt) * 1000));
      }
    }
  }
  return { success: false, error: lastError || "Unknown email error" };
}

async function sendSmsBrevo(toE164: string, content: string): Promise<SendSmsResult> {
  if (!BREVO_API_KEY) {
    return { success: false, error: "BREVO_API_KEY not configured" };
  }
  const res = await fetch("https://api.brevo.com/v3/transactionalSMS/sms", {
    method: "POST",
    headers: {
      "api-key": BREVO_API_KEY,
      "Content-Type": "application/json",
      Accept: "application/json",
    },
    body: JSON.stringify({
      sender: BREVO_SMS_SENDER.slice(0, 11),
      recipient: toE164,
      content,
      type: "transactional",
    }),
  });
  if (!res.ok) {
    return { success: false, provider: "brevo", error: await res.text() };
  }
  return { success: true, provider: "brevo", result: await res.json() };
}

async function sendSmsTwilio(toE164: string, content: string): Promise<SendSmsResult> {
  if (!TWILIO_ACCOUNT_SID || !TWILIO_AUTH_TOKEN || !TWILIO_FROM_NUMBER) {
    return { success: false, error: "Twilio env vars not configured" };
  }
  const auth = btoa(`${TWILIO_ACCOUNT_SID}:${TWILIO_AUTH_TOKEN}`);
  const body = new URLSearchParams({
    To: toE164,
    From: TWILIO_FROM_NUMBER,
    Body: content,
  });
  const res = await fetch(
    `https://api.twilio.com/2010-04-01/Accounts/${TWILIO_ACCOUNT_SID}/Messages.json`,
    {
      method: "POST",
      headers: {
        Authorization: `Basic ${auth}`,
        "Content-Type": "application/x-www-form-urlencoded",
      },
      body,
    },
  );
  if (!res.ok) {
    return { success: false, provider: "twilio", error: await res.text() };
  }
  return { success: true, provider: "twilio", result: await res.json() };
}

/**
 * Send an SMS. Skips when phone is missing or customer has opted out.
 * @param smsOptIn - when false, skip; when undefined/true, send
 */
export async function sendSms(
  phone: string | null | undefined,
  content: string,
  options: { smsOptIn?: boolean | null } = {},
): Promise<SendSmsResult> {
  if (options.smsOptIn === false) {
    return { success: true, skipped: true, reason: "sms_opt_out" };
  }
  const toE164 = normalizePhoneE164(phone);
  if (!toE164) {
    return { success: true, skipped: true, reason: "invalid_phone" };
  }

  try {
    if (SMS_PROVIDER === "twilio") {
      return await sendSmsTwilio(toE164, content);
    }
    return await sendSmsBrevo(toE164, content);
  } catch (err) {
    return {
      success: false,
      error: err instanceof Error ? err.message : String(err),
    };
  }
}

/**
 * Booking time slot parsing, mirroring the SQL functions of the same name.
 *
 * Stored slots come in four shapes depending on which code path wrote the row: '6:00 AM',
 * '06:00:00', '06:00:00|08:00:00' and '08:00|17:00'. Anything that reasons about booking times
 * has to handle all four, and previously each caller handled a different subset.
 *
 * Prefer the typed bookings.*_window_start / *_window_end columns where they are available;
 * these helpers exist for rows written before those columns existed and for callers that only
 * have the text value to hand.
 *
 * Keep in sync with public.parse_clock_time and public.parse_booking_time_slot.
 */

export const BUSINESS_TIME_ZONE = "America/Denver";

export type ClockTime = { hour: number; minute: number; second: number };
export type TimeWindow = { start: ClockTime; end: ClockTime };

const TWELVE_HOUR = /^(\d{1,2}):(\d{2})(?::(\d{2}))?\s*(AM|PM)$/i;
const TWENTY_FOUR_HOUR = /^(\d{1,2}):(\d{2})(?::(\d{2}))?$/;

/** Parses HH:mm, HH:mm:ss or h:mm AM/PM. Returns null for anything unrecognised. */
export function parseClockTime(value: string | null | undefined): ClockTime | null {
  if (typeof value !== "string") return null;
  const raw = value.trim();
  if (!raw) return null;

  const twelve = TWELVE_HOUR.exec(raw);
  if (twelve) {
    let hour = parseInt(twelve[1], 10) % 12;
    if (twelve[4].toUpperCase() === "PM") hour += 12;
    const minute = parseInt(twelve[2], 10);
    const second = twelve[3] ? parseInt(twelve[3], 10) : 0;
    if (minute > 59 || second > 59) return null;
    return { hour, minute, second };
  }

  const twentyFour = TWENTY_FOUR_HOUR.exec(raw);
  if (twentyFour) {
    const hour = parseInt(twentyFour[1], 10);
    const minute = parseInt(twentyFour[2], 10);
    const second = twentyFour[3] ? parseInt(twentyFour[3], 10) : 0;
    if (hour > 23 || minute > 59 || second > 59) return null;
    return { hour, minute, second };
  }

  return null;
}

function toMinutes(t: ClockTime): number {
  return t.hour * 60 + t.minute;
}

/**
 * Normalises any stored slot into a start/end window.
 *
 * @param spanMinutes How long a single-valued slot lasts. Pass 0 for services whose slot is an
 *   instant rather than a window (hourly self-pickup stores a collection time and a return-by
 *   deadline, not a window).
 */
export function parseBookingTimeSlot(
  slot: string | null | undefined,
  spanMinutes = 120,
): TimeWindow | null {
  if (typeof slot !== "string") return null;
  const raw = slot.trim();
  if (!raw) return null;

  if (raw.includes("|")) {
    const [leftRaw, rightRaw] = raw.split("|");
    const start = parseClockTime(leftRaw);
    const end = parseClockTime(rightRaw);
    if (!start || !end) return null;
    return { start, end };
  }

  const start = parseClockTime(raw);
  if (!start) return null;

  const span = Math.max(spanMinutes ?? 0, 0);
  if (span === 0) return { start, end: { ...start } };

  const endMinutes = toMinutes(start) + span;
  // A late slot plus its span can run past midnight, which would leave end before start and
  // break every overlap test. Clamp to the end of the day instead.
  if (endMinutes >= 24 * 60) {
    return { start, end: { hour: 23, minute: 59, second: 59 } };
  }
  return {
    start,
    end: { hour: Math.floor(endMinutes / 60), minute: endMinutes % 60, second: 0 },
  };
}

/** Minutes the given zone is offset from UTC at a particular instant (negative west of UTC). */
function zoneOffsetMinutes(instant: Date, timeZone: string): number {
  const parts = new Intl.DateTimeFormat("en-US", {
    timeZone,
    hour12: false,
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
  }).formatToParts(instant);

  const field = (type: string) => Number(parts.find((p) => p.type === type)?.value ?? "0");
  // Intl renders midnight as hour 24 in some runtimes; normalise it.
  const hour = field("hour") % 24;

  const asIfUtc = Date.UTC(
    field("year"),
    field("month") - 1,
    field("day"),
    hour,
    field("minute"),
    field("second"),
  );
  return (asIfUtc - instant.getTime()) / 60000;
}

/**
 * Converts a wall-clock date and time in the business timezone into a real UTC instant.
 *
 * The offset depends on the instant we are trying to find, so this resolves it in two passes:
 * guess using the offset at the naive instant, then re-check the offset at that result. That
 * matters because America/Denver is UTC-7 in winter and UTC-6 in summer, and the previous
 * implementation hardcoded a single offset.
 */
export function businessWallTimeToUtc(
  dateIso: string,
  time: ClockTime,
  timeZone: string = BUSINESS_TIME_ZONE,
): Date | null {
  const dateMatch = /^(\d{4})-(\d{2})-(\d{2})/.exec(dateIso ?? "");
  if (!dateMatch) return null;

  const naive = Date.UTC(
    Number(dateMatch[1]),
    Number(dateMatch[2]) - 1,
    Number(dateMatch[3]),
    time.hour,
    time.minute,
    time.second,
  );

  const firstOffset = zoneOffsetMinutes(new Date(naive), timeZone);
  let resolved = new Date(naive - firstOffset * 60000);

  const secondOffset = zoneOffsetMinutes(resolved, timeZone);
  if (secondOffset !== firstOffset) {
    resolved = new Date(naive - secondOffset * 60000);
  }
  return resolved;
}

/** Formats a ClockTime as HH:mm:ss, matching the Postgres `time` text representation. */
export function formatClockTime(time: ClockTime): string {
  const pad = (n: number) => String(n).padStart(2, "0");
  return `${pad(time.hour)}:${pad(time.minute)}:${pad(time.second)}`;
}

import {
  BUSINESS_TIME_ZONE,
  businessWallTimeToUtc,
  type ClockTime,
  parseBookingTimeSlot,
  parseClockTime,
} from "./parseBookingTimeSlot.ts";

export const PIN_LEAD_TIME_MS = 12 * 60 * 60 * 1000;
/** Extra hour the padlock PIN stays valid after the scheduled booking end. */
export const RETURN_GRACE_MS = 60 * 60 * 1000;
/** Activate the PIN this many ms before drop-off so it works the instant they arrive. */
export const PIN_EARLY_ACTIVATION_MS = 5 * 60 * 1000;
/** Second customer PIN message this many ms before drop-off. */
export const PIN_REMINDER_LEAD_MS = 60 * 60 * 1000;

/** Calendar YYYY-MM-DD in the yard timezone. */
export function denverCalendarDate(now: Date = new Date()): string {
  const parts = new Intl.DateTimeFormat("en-US", {
    timeZone: BUSINESS_TIME_ZONE,
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
  }).formatToParts(now);
  const year = parts.find((p) => p.type === "year")?.value;
  const month = parts.find((p) => p.type === "month")?.value;
  const day = parts.find((p) => p.type === "day")?.value;
  return `${year}-${month}-${day}`;
}

export function addCalendarDays(ymd: string, days: number): string {
  const [year, month, day] = ymd.split("-").map(Number);
  const utc = Date.UTC(year, month - 1, day + days);
  return new Date(utc).toISOString().slice(0, 10);
}

/** Overnight lock programming: drop-off is today or tomorrow in Denver. */
export function isDropOffTodayOrTomorrow(
  booking: BookingWindowFields,
  now: Date = new Date(),
): boolean {
  const drop = booking.drop_off_date;
  if (!drop) return false;
  const today = denverCalendarDate(now);
  const tomorrow = addCalendarDays(today, 1);
  return drop === today || drop === tomorrow;
}

/** First PIN email/SMS: lock may already hold the code; customer is told from 12h before drop-off. */
export function isDueForFirstPinNotify(
  booking: BookingWindowFields,
  now: Date = new Date(),
): boolean {
  if (!booking.drop_off_date) return false;
  const { startMs, graceEndMs } = getBookingWindow(booking);
  if (!Number.isFinite(startMs) || !Number.isFinite(graceEndMs)) return false;
  const nowMs = now.getTime();
  return nowMs >= startMs - PIN_LEAD_TIME_MS && nowMs < graceEndMs;
}

/** 1-hour reminder: after the first PIN message, from 1h before drop-off until 15 minutes after it. */
export function isDueForPinReminder(
  booking: BookingWindowFields,
  now: Date = new Date(),
): boolean {
  if (!booking.drop_off_date) return false;
  const { startMs } = getBookingWindow(booking);
  if (!Number.isFinite(startMs)) return false;
  const nowMs = now.getTime();
  return nowMs >= startMs - PIN_REMINDER_LEAD_MS && nowMs < startMs + 15 * 60 * 1000;
}

/**
 * When a booking has no usable time at all, assume the yard's normal operating bounds. These
 * are business-local hours, not UTC: the previous implementation used UTC fallbacks, and the
 * end fallback of 05:00 UTC actually resolved to 11pm local on the day *before* pickup, which
 * made such bookings look finished before they began.
 */
const DEFAULT_START_LOCAL: ClockTime = { hour: 6, minute: 0, second: 0 };
const DEFAULT_END_LOCAL: ClockTime = { hour: 23, minute: 0, second: 0 };

export type BookingWindowFields = {
  drop_off_date?: string | null;
  drop_off_time_slot?: string | null;
  pickup_date?: string | null;
  pickup_time_slot?: string | null;
  /** Typed columns added in the time-window normalisation migration; preferred when present. */
  drop_off_window_start?: string | null;
  drop_off_window_end?: string | null;
  pickup_window_start?: string | null;
  pickup_window_end?: string | null;
};

/**
 * Resolve a booking-local wall time, preferring the typed column and falling back to parsing
 * the legacy text slot. `edge` picks which end of a window to use.
 */
function resolveLocalTime(
  typedValue: string | null | undefined,
  textSlot: string | null | undefined,
  edge: "start" | "end",
  fallback: ClockTime,
): ClockTime {
  const typed = parseClockTime(typedValue);
  if (typed) return typed;

  const parsed = parseBookingTimeSlot(textSlot, 0);
  if (parsed) return edge === "start" ? parsed.start : parsed.end;

  return fallback;
}

export function buildBookingDateUTC(
  date: string,
  timeSlot: string | null | undefined,
  fallbackLocalHour: number,
): string {
  const parsed = parseBookingTimeSlot(timeSlot, 0);
  const local = parsed?.start ?? { hour: fallbackLocalHour, minute: 0, second: 0 };
  const instant = businessWallTimeToUtc(date, local, BUSINESS_TIME_ZONE);
  if (!instant) {
    return `${date}T${String(fallbackLocalHour).padStart(2, "0")}:00:00+00:00`;
  }
  return instant.toISOString();
}

/** Add RETURN_GRACE_MS to an ISO date string and return a new ISO (+00:00) string. */
export function addGraceHour(isoDate: string): string {
  const ms = new Date(isoDate).getTime() + RETURN_GRACE_MS;
  return new Date(ms).toISOString().replace(/\.\d{3}Z$/, "+00:00");
}

/**
 * AlgoPIN rejects starts that aren't whole-hour and rejects the JS `.000Z` suffix.
 * Required shape: `YYYY-MM-DDTHH:00:00+00:00` (see Igloohome onetime AlgoPIN docs).
 */
export function formatAlgoPinStartIso(isoDate: string): string {
  const d = new Date(isoDate);
  if (Number.isNaN(d.getTime())) return isoDate;
  d.setUTCMinutes(0, 0, 0);
  return d.toISOString().replace(/\.\d{3}Z$/, "+00:00");
}

/**
 * Igloohome rejects a duration PIN whose startDate falls before the current hour.
 * Raises a past start up to the top of the current hour; leaves future starts alone.
 */
export function clampIgloohomeStart(isoDate: string, now: Date = new Date()): string {
  const hourFloor = new Date(now.getTime());
  hourFloor.setUTCMinutes(0, 0, 0);
  const ms = Math.max(new Date(isoDate).getTime(), hourFloor.getTime());
  return new Date(ms).toISOString().replace(/\.\d{3}Z$/, "+00:00");
}

export function getBookingWindow(booking: BookingWindowFields) {
  const startLocal = resolveLocalTime(
    booking.drop_off_window_start,
    booking.drop_off_time_slot,
    "start",
    DEFAULT_START_LOCAL,
  );
  const endLocal = resolveLocalTime(
    booking.pickup_window_end ?? booking.pickup_window_start,
    booking.pickup_time_slot,
    "end",
    DEFAULT_END_LOCAL,
  );

  const startDate = businessWallTimeToUtc(booking.drop_off_date ?? "", startLocal);
  const endDate = businessWallTimeToUtc(booking.pickup_date ?? "", endLocal);

  const startMs = startDate ? startDate.getTime() : NaN;
  const endMs = endDate ? endDate.getTime() : NaN;
  const graceEndMs = endMs + RETURN_GRACE_MS;
  const graceEndIso = Number.isFinite(graceEndMs)
    ? new Date(graceEndMs).toISOString().replace(/\.\d{3}Z$/, "+00:00")
    : "";
  const activationMs = startMs - PIN_EARLY_ACTIVATION_MS;
  const activationIso = Number.isFinite(activationMs)
    ? new Date(activationMs).toISOString().replace(/\.\d{3}Z$/, "+00:00")
    : "";

  return {
    startMs,
    endMs,
    graceEndMs,
    pinEligibleFromMs: startMs - PIN_LEAD_TIME_MS,
    activationMs,
    activationIso,
    startIso: startDate ? startDate.toISOString() : "",
    endIso: endDate ? endDate.toISOString() : "",
    graceEndIso,
  };
}

/**
 * PIN start sent to Igloohome: booking drop-off minus 5 minutes, clamped to the
 * current hour so Igloohome accepts it. Customers still see the appointment time.
 */
export function getPinActivationStart(
  booking: BookingWindowFields,
  now: Date = new Date(),
): string {
  const { activationIso } = getBookingWindow(booking);
  return clampIgloohomeStart(activationIso, now);
}

/** Scheduled return time with no grace — for all customer-facing copy. */
export function getCustomerVisibleEndIso(booking: BookingWindowFields): string {
  return getBookingWindow(booking).endIso;
}

export function isWithinPinGenerationWindow(
  booking: BookingWindowFields,
  now: Date = new Date(),
): boolean {
  if (!booking.drop_off_date || !booking.pickup_date) return false;
  const { pinEligibleFromMs, graceEndMs } = getBookingWindow(booking);
  if (!Number.isFinite(pinEligibleFromMs) || !Number.isFinite(graceEndMs)) return false;
  const nowMs = now.getTime();
  return nowMs >= pinEligibleFromMs && nowMs < graceEndMs;
}

export function isBookingEnded(
  booking: BookingWindowFields,
  now: Date = new Date(),
): boolean {
  if (!booking.pickup_date) return false;
  const { graceEndMs } = getBookingWindow(booking);
  if (!Number.isFinite(graceEndMs)) return false;
  return now.getTime() >= graceEndMs;
}

export function getPinWindowSkipReason(
  booking: BookingWindowFields,
  now: Date = new Date(),
): "too_early" | "ended" | null {
  if (!booking.drop_off_date || !booking.pickup_date) return "too_early";
  const { pinEligibleFromMs, graceEndMs } = getBookingWindow(booking);
  if (!Number.isFinite(pinEligibleFromMs) || !Number.isFinite(graceEndMs)) return "too_early";
  const nowMs = now.getTime();
  if (nowMs < pinEligibleFromMs) return "too_early";
  if (nowMs >= graceEndMs) return "ended";
  return null;
}

/** The columns getBookingWindow needs, for edge functions building their booking selects. */
export const BOOKING_WINDOW_COLUMNS =
  "drop_off_date, pickup_date, drop_off_time_slot, pickup_time_slot, " +
  "drop_off_window_start, drop_off_window_end, pickup_window_start, pickup_window_end";

/**
 * igloohome-webhook
 *
 * Public endpoint for igloohome webhook deliveries. Routes on the event type
 * in `payload.payload.event.type`:
 *
 *   3  Job Complete           — result of a command we issued (lock_jobs)
 *   5  Activity Log Received  — real activity at the lock (the primary event)
 *   10 Bridge Connection      — bridge network connectivity heartbeat
 *
 * Register in the igloohome portal:
 *   https://<project>.supabase.co/functions/v1/igloohome-webhook
 *
 * Requires `verify_jwt = false` (see supabase/config.toml) because igloohome
 * authenticates with the x-igloocompany-sha256 signature, not a JWT.
 */

import { createClient } from "https://esm.sh/@supabase/supabase-js@2.45.4";
import { getCorsHeaders } from "./cors.ts";
import {
  type LockActivityEvent,
  parseActivityLogEntry,
  redactPins,
} from "../_shared/iglooActivity.ts";
import { applyLockEvent, sweepGraceHourReturns } from "../_shared/lockEventState.ts";
import {
  defaultBridgeId,
  defaultDeviceId,
  type RecordedEvent,
  recordDeviceEvents,
} from "../_shared/lockDeviceState.ts";
import { verifyIglooWebhook } from "../_shared/iglooWebhookAuth.ts";
import { alertBreakInAttempt, alertBridgeOfflineWhileUnlocked } from "../_shared/lockAlerts.ts";

// deno-lint-ignore no-explicit-any
type SupabaseClient = any;

const EVENT_JOB_COMPLETE = 3;
const EVENT_ACTIVITY_LOG = 5;
const EVENT_BRIDGE_CONNECTION = 10;

function makeJsonResponse(corsHeaders: Record<string, string>) {
  return (body: unknown, status = 200) =>
    new Response(JSON.stringify(body), {
      status,
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
}

function asRecord(value: unknown): Record<string, unknown> | null {
  if (value && typeof value === "object" && !Array.isArray(value)) {
    return value as Record<string, unknown>;
  }
  return null;
}

function pickString(obj: Record<string, unknown> | null, keys: string[]): string | null {
  if (!obj) return null;
  for (const key of keys) {
    const val = obj[key];
    if (typeof val === "string" && val.trim()) return val.trim();
    if (typeof val === "number") return String(val);
  }
  return null;
}

/** Igloohome nests as `{ payload: { event: {...} } }`; tolerate a flatter shape too. */
function extractEvent(body: unknown): Record<string, unknown> | null {
  const root = asRecord(body);
  if (!root) return null;
  return asRecord(asRecord(root.payload)?.event) ||
    asRecord(root.event) ||
    asRecord(root.payload) ||
    root;
}

function eventTypeOf(event: Record<string, unknown> | null): number | null {
  if (!event) return null;
  const val = event.type ?? event.eventType;
  if (typeof val === "number") return val;
  if (typeof val === "string" && /^\d+$/.test(val.trim())) return Number(val.trim());
  return null;
}

const JOB_TYPE_CREATE_PIN = 4;
const JOB_TYPE_DELETE_PIN = 5;

/** Igloohome job statuses: 0 = completed, 2 = failed (matches _shared/lockPin.ts pollJob). */
function isJobCompleted(jobStatus: unknown, completedFlag: unknown): boolean {
  return completedFlag === true || jobStatus === 0;
}

/**
 * Job Complete tells us the *result* of a create/delete we issued. Use it to
 * flip rental_access_codes.lock_confirmed_at / lock_deleted_at immediately
 * instead of waiting for the next reconciler sweep to poll the job.
 */
async function reconcilePinFromJob(
  supabase: SupabaseClient,
  jobId: string,
  jobType: number | null,
  jobStatus: unknown,
  completedFlag: unknown,
): Promise<{ orderId: number; booking: Record<string, unknown> } | null> {
  if (!isJobCompleted(jobStatus, completedFlag)) return null;
  if (jobType !== JOB_TYPE_CREATE_PIN && jobType !== JOB_TYPE_DELETE_PIN) return null;

  const { data: pinRow } = await supabase
    .from("rental_access_codes")
    .select("id, order_id, access_pin, pin_type, start_time, end_time, lock_confirmed_at, lock_deleted_at")
    .eq("pin_id", jobId)
    .eq("pin_type", "bridge_proxied")
    .maybeSingle();
  if (!pinRow) return null;

  const nowIso = new Date().toISOString();

  if (jobType === JOB_TYPE_CREATE_PIN && !pinRow.lock_confirmed_at) {
    await supabase.from("rental_access_codes").update({ lock_confirmed_at: nowIso }).eq("id", pinRow.id);
    console.log(`[igloohome-webhook] Job ${jobId}: create confirmed for order #${pinRow.order_id}`);
    const { data: booking } = await supabase
      .from("bookings")
      .select("*")
      .eq("id", pinRow.order_id)
      .maybeSingle();
    if (booking) return { orderId: pinRow.order_id, booking };
    return null;
  }

  if (jobType === JOB_TYPE_DELETE_PIN && !pinRow.lock_deleted_at) {
    await supabase
      .from("rental_access_codes")
      .update({ status: "expired", lock_deleted_at: nowIso })
      .eq("id", pinRow.id);
    console.log(`[igloohome-webhook] Job ${jobId}: delete confirmed for order #${pinRow.order_id}`);
  }

  return null;
}

async function handleJobComplete(
  supabase: SupabaseClient,
  event: Record<string, unknown>,
): Promise<{ result: Record<string, unknown>; pinConfirmed: { orderId: number; booking: Record<string, unknown> } | null }> {
  const data = asRecord(event.data) || event;
  const jobId = pickString(data, ["jobId", "job_id", "id"]);
  if (!jobId) return { result: { handled: false, reason: "missing jobId" }, pinConfirmed: null };

  const jobStatusRaw = data.jobStatus ?? data.job_status ?? asRecord(data.jobResponse)?.jobStatus;
  const jobTypeRaw = data.jobType ?? data.job_type;
  const jobType = typeof jobTypeRaw === "number" ? jobTypeRaw : null;
  const deviceId = pickString(data, ["deviceId", "device_id", "lockId"]) || defaultDeviceId();

  const { error } = await supabase.from("lock_jobs").upsert({
    job_id: jobId,
    device_id: deviceId,
    job_type: jobType,
    job_status: typeof jobStatusRaw === "number" ? jobStatusRaw : null,
    raw: redactPins(event),
    updated_at: new Date().toISOString(),
  }, { onConflict: "job_id" });

  if (error) console.error("[igloohome-webhook] lock_jobs upsert failed:", error.message);

  let pinConfirmed: { orderId: number; booking: Record<string, unknown> } | null = null;
  try {
    pinConfirmed = await reconcilePinFromJob(supabase, jobId, jobType, jobStatusRaw, data.completed);
  } catch (err) {
    console.error("[igloohome-webhook] reconcilePinFromJob failed:", err);
  }

  return { result: { handled: !error, jobId, jobStatus: jobStatusRaw ?? null }, pinConfirmed };
}

/**
 * Fire-and-forget call into the reconciler so a bridge reconnect flushes any
 * PIN create/delete that got stuck while it was offline, instead of waiting
 * for the next overnight cron sweep. Customer PIN email waits until 5am Denver.
 */
async function triggerReconciler(reason: string): Promise<void> {
  try {
    const supabaseUrl = Deno.env.get("SUPABASE_URL");
    const serviceKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY");
    if (!supabaseUrl || !serviceKey) return;
    const res = await fetch(`${supabaseUrl}/functions/v1/reconcile-lock-pins`, {
      method: "POST",
      headers: {
        Authorization: `Bearer ${serviceKey}`,
        apikey: serviceKey,
        "Content-Type": "application/json",
      },
      body: JSON.stringify({ reason }),
    });
    console.log(`[igloohome-webhook] Reconciler flush (${reason}) -> HTTP ${res.status}`);
  } catch (err) {
    console.error(`[igloohome-webhook] Reconciler flush (${reason}) failed:`, err);
  }
}

async function handleBridgeConnection(
  supabase: SupabaseClient,
  event: Record<string, unknown>,
): Promise<{ result: Record<string, unknown>; alerts: Array<() => Promise<void>> }> {
  const data = asRecord(event.data) || event;
  const bridgeId = pickString(data, ["bridgeId", "bridge_id", "deviceId", "id"]) ||
    defaultBridgeId();
  if (!bridgeId) return { result: { handled: false, reason: "missing bridgeId" }, alerts: [] };

  const rawOnline = data.isOnline ?? data.online ?? data.connected ?? data.connectionStatus ??
    data.status;
  let isOnline: boolean | null = null;
  if (typeof rawOnline === "boolean") isOnline = rawOnline;
  else if (typeof rawOnline === "number") isOnline = rawOnline === 1;
  else if (typeof rawOnline === "string") {
    isOnline = /^(1|true|online|connected)$/i.test(rawOnline.trim());
  }

  const now = new Date().toISOString();
  const { data: previous } = await supabase
    .from("lock_bridges")
    .select("bridge_id, is_online")
    .eq("bridge_id", bridgeId)
    .maybeSingle();

  const changed = previous?.is_online !== isOnline;
  const { error } = await supabase.from("lock_bridges").upsert({
    bridge_id: bridgeId,
    is_online: isOnline,
    last_event_at: now,
    ...(changed ? { last_changed_at: now } : {}),
  }, { onConflict: "bridge_id" });
  if (error) console.error("[igloohome-webhook] lock_bridges upsert failed:", error.message);

  const alerts: Array<() => Promise<void>> = [];

  // Bridge just came back — flush any PIN create/delete that got stuck
  // while it was unreachable instead of waiting for the next cron sweep.
  if (isOnline === true && changed) {
    alerts.push(() => triggerReconciler("bridge_reconnect"));
  }

  // Losing connectivity while a lock is still open is the worst case: the
  // equipment is accessible and we will not hear about further activity.
  if (isOnline === false && changed) {
    const { data: openDevices } = await supabase
      .from("lock_devices")
      .select("device_id, label, state_changed_at")
      .eq("bridge_id", bridgeId)
      .eq("current_state", "unlocked")
      .eq("is_active", true);
    for (const device of openDevices ?? []) {
      alerts.push(() =>
        alertBridgeOfflineWhileUnlocked({
          bridgeId,
          deviceId: device.device_id,
          label: device.label,
          lastStateChangedAt: device.state_changed_at,
        })
      );
    }
  }

  return { result: { handled: !error, bridgeId, isOnline, changed }, alerts };
}

async function handleActivityLogs(
  supabase: SupabaseClient,
  event: Record<string, unknown>,
): Promise<{ recorded: RecordedEvent[]; parsed: number; stored: number }> {
  const data = asRecord(event.data) || event;
  const logs = Array.isArray(data.activityLogs)
    ? data.activityLogs
    : Array.isArray(data.activity_logs)
    ? data.activity_logs
    : Array.isArray(data.logs)
    ? data.logs
    : [];

  const parsedEvents: LockActivityEvent[] = [];
  for (const entry of logs) {
    const parsed = parseActivityLogEntry(entry);
    if (parsed) parsedEvents.push(parsed);
  }

  const { recorded, stored } = await recordDeviceEvents(supabase, parsedEvents, {
    deviceId: pickString(data, ["deviceId", "device_id", "lockId", "productId"]),
    bridgeId: pickString(data, ["bridgeId", "bridge_id"]),
  });

  return { recorded, parsed: parsedEvents.length, stored };
}

/**
 * Booking state changes run after the 200 so igloohome never retries because
 * an email provider was slow. Customer PIN email/SMS is sent by the 5am Denver
 * reconcile-lock-pins cron, not here.
 */
async function processDeferred(
  supabase: SupabaseClient,
  recorded: RecordedEvent[],
  bridgeAlerts: Array<() => Promise<void>>,
): Promise<void> {
  try {
    for (const { event, deviceId, orderId } of recorded) {
      if (event.eventType === "breakin") {
        const { data: device } = await supabase
          .from("lock_devices")
          .select("label")
          .eq("device_id", deviceId)
          .maybeSingle();
        await alertBreakInAttempt({
          deviceId,
          label: device?.label ?? null,
          occurredAt: event.eventTimestamp,
          orderId,
        });
      }

      if (!orderId) continue;
      const action = await applyLockEvent(supabase, {
        orderId,
        eventType: event.eventType,
        eventTimestamp: event.eventTimestamp,
        notes: `${event.eventType} via igloohome-webhook (logType ${event.logType ?? "n/a"})`,
      });
      console.log(`[igloohome-webhook] Booking #${orderId}: ${action}`);
    }

    for (const alert of bridgeAlerts) await alert();

    if (recorded.length > 0) {
      await sweepGraceHourReturns(supabase);
    }
  } catch (err) {
    console.error("[igloohome-webhook] Deferred processing failed:", err);
  }
}

function runDeferred(work: Promise<unknown>): void {
  // deno-lint-ignore no-explicit-any
  const runtime = (globalThis as any).EdgeRuntime;
  if (runtime && typeof runtime.waitUntil === "function") {
    runtime.waitUntil(work);
    return;
  }
  work.catch((err) => console.error("[igloohome-webhook] Deferred work rejected:", err));
}

Deno.serve(async (req) => {
  const corsHeaders = getCorsHeaders(req);
  const jsonResponse = makeJsonResponse(corsHeaders);

  if (req.method === "OPTIONS") {
    return new Response(null, { headers: corsHeaders });
  }
  if (req.method !== "POST") {
    return jsonResponse({ success: false, error: "Method not allowed" }, 405);
  }

  try {
    const rawBody = await req.text();
    const verification = await verifyIglooWebhook(req, rawBody);
    if (!verification.valid) {
      console.warn(
        `[igloohome-webhook] Signature rejected (${verification.method}): ${verification.reason}`,
      );
      return jsonResponse({ success: false, error: "Invalid signature" }, 401);
    }

    let body: unknown = null;
    try {
      body = rawBody ? JSON.parse(rawBody) : null;
    } catch {
      return jsonResponse({ success: false, error: "Invalid JSON" }, 400);
    }

    const supabaseUrl = Deno.env.get("SUPABASE_URL");
    const serviceKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY");
    if (!supabaseUrl || !serviceKey) {
      return jsonResponse({ success: false, error: "Missing Supabase env" }, 500);
    }
    const supabase = createClient(supabaseUrl, serviceKey);

    const event = extractEvent(body);
    const type = eventTypeOf(event);
    console.log("[igloohome-webhook] Verified event", JSON.stringify({
      verifiedBy: verification.method,
      eventType: type,
      payload: redactPins(body),
    }));

    if (type === EVENT_JOB_COMPLETE) {
      const { result } = await handleJobComplete(supabase, event!);
      return jsonResponse({ success: true, eventType: type, ...result });
    }

    if (type === EVENT_BRIDGE_CONNECTION) {
      const { result, alerts } = await handleBridgeConnection(supabase, event!);
      if (alerts.length > 0) runDeferred(processDeferred(supabase, [], alerts));
      return jsonResponse({ success: true, eventType: type, ...result });
    }

    if (type === EVENT_ACTIVITY_LOG) {
      const { recorded, parsed, stored } = await handleActivityLogs(supabase, event!);
      runDeferred(processDeferred(supabase, recorded, []));
      return jsonResponse({
        success: true,
        eventType: type,
        eventsParsed: parsed,
        eventsStored: stored,
        verifiedBy: verification.method,
      });
    }

    console.log(`[igloohome-webhook] Unhandled event type: ${type}`);
    return jsonResponse({ success: true, eventType: type, handled: false });
  } catch (error) {
    console.error("[igloohome-webhook] Unhandled:", error);
    return jsonResponse({
      success: false,
      error: error instanceof Error ? error.message : String(error),
    }, 500);
  }
});
